// FUNCTION: BFME2 0x004A57DB size=112 name=?doAngleFX@StructureToppleUpdate@@IAEXMM@Z evidence=N:ledger tier=A
void StructureToppleUpdate::doAngleFX(Real fromAngle, Real toAngle)
{
	const StructureToppleUpdateModuleData *data = (const StructureToppleUpdateModuleData *)getModuleData();
	const DamageInfo *lastDamage = getObject()->getBodyModule()->getLastDamageInfo();
	for (const StructureToppleAngleFX *entry = data->m_angleFXs.begin(); entry != data->m_angleFXs.end(); ++entry)
	{
		if (entry->m_angle > fromAngle && toAngle >= entry->m_angle)
		{
			if (!lastDamage || getDamageTypeFlag(data->m_damageFXTypes, lastDamage->in.m_damageType))
				FXList::doFXObj(entry->m_fx, getObject(), 0);
		}
	}
}

