// FUNCTION: BFME2 0x004A5947 size=450 name=?doDamageLine@StructureToppleUpdate@@IAEXPAVObject@@PBVWeaponTemplate@@MMMM@Z evidence=N:ledger tier=A
void StructureToppleUpdate::doDamageLine(Object *building, const WeaponTemplate *weaponTemplate, Real jcos, Real jsin, Real facingWidth, Real toppleAngle)
{
	const DamageInfo *lastDamageInfo = getObject()->getBodyModule()->getLastDamageInfo();
	static const Real WEAPON_SPACING_PARALLEL = 25;
	const StructureToppleUpdateModuleData *d = (const StructureToppleUpdateModuleData *)getModuleData();
	Coord3D target;

	for (Real i = -facingWidth; i < facingWidth; i += WEAPON_SPACING_PARALLEL)
	{
		target.x = building->getPosition()->x + jcos + (i * Sin(toppleAngle));
		target.y = building->getPosition()->y + jsin + (i * Cos(toppleAngle));
		target.z = TheTerrainLogic->getGroundHeight(target.x, target.y);
		TheWeaponStore->createAndFireTempWeapon(weaponTemplate, building, &target);
		if (lastDamageInfo == NULL || getDamageTypeFlag(d->m_damageFXTypes, lastDamageInfo->in.m_damageType))
			FXList::doFXPos(d->m_crushingFX, &target, 0, 0.0f, 0);
	}

	target.x = building->getPosition()->x + jcos + (facingWidth * Sin(toppleAngle));
	target.y = building->getPosition()->y + jsin + (facingWidth * Cos(toppleAngle));
	target.z = TheTerrainLogic->getGroundHeight(target.x, target.y);
	TheWeaponStore->createAndFireTempWeapon(weaponTemplate, building, &target);
	if (lastDamageInfo == NULL || getDamageTypeFlag(d->m_damageFXTypes, lastDamageInfo->in.m_damageType))
		FXList::doFXPos(d->m_crushingFX, &target, 0, 0.0f, 0);

	target.x = building->getPosition()->x + jcos;
	target.y = building->getPosition()->y + jsin;
	target.z = TheTerrainLogic->getGroundHeight(target.x, target.y);
	doPhaseStuff(STRUCTURE_TOPPLE_PHASE_FINAL, &target);
}

// FUNCTION: BFME2 0x004A5B09 size=88 name=?doToppleStartFX@StructureToppleUpdate@@IAEXPAVObject@@PBVDamageInfo@@@Z evidence=N:ledger tier=A
void StructureToppleUpdate::doToppleStartFX(Object *obj, const DamageInfo *damageInfo)
{
	const StructureToppleUpdateModuleData *data = (const StructureToppleUpdateModuleData *)getModuleData();
	const DamageInfo *lastDamage = getObject()->getBodyModule()->getLastDamageInfo();
	if (!lastDamage || getDamageTypeFlag(data->m_damageFXTypes, lastDamage->in.m_damageType))
		FXList::doFXPos(data->m_toppleStartFX, obj->getPosition(), 0, 0.0f, 0);
	doPhaseStuff(STRUCTURE_TOPPLE_PHASE_INITIAL, obj->getPosition());
}

// FUNCTION: BFME2 0x004A5B61 size=299 name=?doToppleDelayBurstFX@StructureToppleUpdate@@IAEXXZ evidence=N:ledger tier=A
void StructureToppleUpdate::doToppleDelayBurstFX()
{
	const StructureToppleUpdateModuleData *d = (const StructureToppleUpdateModuleData *)getModuleData();
	const DamageInfo *lastDamageInfo = getObject()->getBodyModule()->getLastDamageInfo();

	if (lastDamageInfo == NULL || getDamageTypeFlag(d->m_damageFXTypes, lastDamageInfo->in.m_damageType))
		FXList::doFXPos(d->m_toppleDelayFX, &m_delayBurstLocation, 0, 0.0f, 0);

	Drawable *drawable = getObject()->getDrawable();

	if (lastDamageInfo == NULL || getDamageTypeFlag(d->m_damageFXTypes, lastDamageInfo->in.m_damageType))
	{
		for (const StructureToppleFXBone *it = d->m_fxBones.begin(); it != d->m_fxBones.end(); ++it)
		{
			ParticleSystemHandle sys = TheParticleSystemManager->createParticleSystem(it->m_particleSystemTemplate, true);
			if (sys)
			{
				Coord3D pos;
				if (drawable->getPristineBonePositions(it->m_boneName.str(), 0, &pos, NULL, 1, 0) == 1)
				{
					sys->setPosition(&pos);
					sys->attachToDrawable(drawable);
				}
			}
		}
	}

	doPhaseStuff(STRUCTURE_TOPPLE_PHASE_DELAY, &m_delayBurstLocation);
}

// FUNCTION: BFME2 0x004A5C8C size=463 name=?beginStructureTopple@StructureToppleUpdate@@IAEXPBVDamageInfo@@@Z evidence=N:ledger tier=A
void StructureToppleUpdate::beginStructureTopple(const DamageInfo *damageInfo)
{
	const StructureToppleUpdateModuleData *d = (const StructureToppleUpdateModuleData *)getModuleData();

	if (d)
	{
		UnsignedInt now = TheGameLogic->getFrame();
		m_toppleFrame = now + GetGameLogicRandomValue(d->m_minToppleDelay, d->m_maxToppleDelay, "C:\\projects\\bfme2patch103\\bfme2\\Code\\GameEngine\\Source\\GameLogic\\Object\\Update\\StructureToppleUpdate.cpp", 0x84);

		Object *attacker = TheGameLogic->findObjectByID(damageInfo->in.m_sourceID);
		Object *building = getObject();

		Real toppleAngle = 0.0f;
		if (d->m_forceToppleAngle != -9.87654f)
		{
			toppleAngle = d->m_forceToppleAngle * 0.017453292f;
			toppleAngle += building->getOrientation();
			toppleAngle = normalizeAngle(toppleAngle);
		}
		else if (attacker == NULL)
		{
			toppleAngle = GetGameLogicRandomValueReal(0.0f, 6.2831855f, "C:\\projects\\bfme2patch103\\bfme2\\Code\\GameEngine\\Source\\GameLogic\\Object\\Update\\StructureToppleUpdate.cpp", 0x97);
		}
		else
		{
			const Coord3D *attackerPos = attacker->getPosition();
			const Coord3D *buildingPos = building->getPosition();

			m_toppleDirection.x = buildingPos->x - attackerPos->x;
			m_toppleDirection.y = buildingPos->y - attackerPos->y;

			toppleAngle = m_toppleDirection.toAngle();
			toppleAngle += GetGameLogicRandomValueReal(-0.39269909f, 0.39269909f, "C:\\projects\\bfme2patch103\\bfme2\\Code\\GameEngine\\Source\\GameLogic\\Object\\Update\\StructureToppleUpdate.cpp", 0xa4);
		}
		m_toppleDirection.x = Cos(toppleAngle);
		m_toppleDirection.y = Sin(toppleAngle);
		TheScriptEngine->adjustToppleDirection(getObject(), &m_toppleDirection);

		Real averageRadius = (building->getGeometryInfo()->getBoundsMinorRadius() + building->getGeometryInfo()->getBoundsMajorRadius()) / 2;
		Real explosionRadius = averageRadius * 0.90;

		m_delayBurstLocation.x = building->getPosition()->x + explosionRadius * Cos(toppleAngle);
		m_delayBurstLocation.y = building->getPosition()->y + explosionRadius * Sin(toppleAngle);
		m_delayBurstLocation.z = TheTerrainLogic->getGroundHeight(m_delayBurstLocation.x, m_delayBurstLocation.y);

		doToppleStartFX(building, damageInfo);
		m_nextBurstFrame = now + GetGameLogicRandomValue(d->m_minToppleBurstDelay, d->m_maxToppleBurstDelay, "C:\\projects\\bfme2patch103\\bfme2\\Code\\GameEngine\\Source\\GameLogic\\Object\\Update\\StructureToppleUpdate.cpp", 0xb5);

		m_toppleState = TOPPLESTATE_WAITINGFORTOPPLESTART;

		setWakeFrame(getObject(), UPDATE_SLEEP_NONE);
	}
}

// FUNCTION: BFME2 0x004A5E5B size=81 name=?onDie@StructureToppleUpdate@@UAEXPBVDamageInfo@@@Z evidence=N:ledger tier=A
void StructureToppleUpdate::onDie(const DamageInfo *damageInfo)
{
	const StructureToppleUpdateModuleData *data = (const StructureToppleUpdateModuleData *)getModuleData();
	if (!data->m_dieMuxData.isDieApplicable(getObject(), damageInfo))
		return;
	if (getObject()->getAI() != NULL)
		getObject()->getAI()->markAsDead();
	TheGameLogic->deselectObject(getObject(), 0xFFFFF, true);
	beginStructureTopple(damageInfo);
}

// FUNCTION: BFME2 0x004A5EAC size=406 name=?applyCrushingDamage@StructureToppleUpdate@@IAEXM@Z evidence=N:ledger tier=A
void StructureToppleUpdate::applyCrushingDamage(Real theta)
{
	static const Real THETA_CEILING = 0.52359877559829887f;
	static const Real WEAPON_SPACING_PERPENDICULAR = 25;

	const StructureToppleUpdateModuleData *d = (const StructureToppleUpdateModuleData *)getModuleData();
	if (theta > THETA_CEILING)
		return;

	Object *building = getObject();
	Real orientationAngle = building->getOrientation();
	Real toppleAngle = m_toppleDirection.toAngle();

	Real angle = orientationAngle - toppleAngle;
	Real minorComponent = building->getGeometryInfo()->getBoundsMinorRadius() * Cos(angle);
	Real majorComponent = building->getGeometryInfo()->getBoundsMajorRadius() * Sin(angle);

	Coord3D temp3D;
	temp3D.x = majorComponent;
	temp3D.y = minorComponent;
	temp3D.z = 0.0f;

	Real facingWidth = temp3D.length() * 0.5f;

	const WeaponTemplate *wt = TheWeaponStore->findWeaponTemplate(d->m_crushingWeaponName);
	if (wt == NULL)
		return;

	Real maxDistance = m_buildingHeight * (1.0 - Sin(theta));

	Real jcos;
	Real jsin;
	Real j;
	for (j = m_lastCrushedLocation; j < maxDistance; j += WEAPON_SPACING_PERPENDICULAR)
	{
		jcos = j * Cos(toppleAngle);
		jsin = j * Sin(toppleAngle);
		doDamageLine(building, wt, jcos, jsin, facingWidth, toppleAngle);
	}

	jcos = maxDistance * Cos(toppleAngle);
	jsin = maxDistance * Sin(toppleAngle);
	doDamageLine(building, wt, jcos, jsin, facingWidth, toppleAngle);

	m_lastCrushedLocation = j;
}

// FUNCTION: BFME2 0x004A6042 size=1065 name=?update@StructureToppleUpdate@@UAE?AW4UpdateSleepTime@@XZ evidence=N:ledger tier=A
UpdateSleepTime StructureToppleUpdate::update()
{
	const StructureToppleUpdateModuleData *d = (const StructureToppleUpdateModuleData *)getModuleData();

	if (m_toppleState == TOPPLESTATE_STANDING)
		return UPDATE_SLEEP_FOREVER;

	const DamageInfo *lastDamageInfo = getObject()->getBodyModule()->getLastDamageInfo();

	if (m_toppleState == TOPPLESTATE_WAITINGFORTOPPLESTART)
	{
		UnsignedInt now = TheGameLogic->getFrame();
		if (now >= m_nextBurstFrame)
		{
			doToppleDelayBurstFX();
			m_nextBurstFrame = now + GetGameLogicRandomValue(d->m_minToppleBurstDelay, d->m_maxToppleBurstDelay, "C:\\projects\\bfme2patch103\\bfme2\\Code\\GameEngine\\Source\\GameLogic\\Object\\Update\\StructureToppleUpdate.cpp", 0xe6);
		}
		if (now >= m_toppleFrame)
		{
			m_toppleState = TOPPLESTATE_TOPPLING;
			m_structuralIntegrity = d->m_structuralIntegrity;
		}
	}

	if (m_toppleState == TOPPLESTATE_TOPPLING)
	{
		UnsignedInt now = TheGameLogic->getFrame();
		Real toppleAcceleration = (Sin(m_accumulatedAngle) * (1.0 - m_structuralIntegrity)) * d->m_toppleAccelerationFactor;
		m_toppleVelocity += toppleAcceleration;

		if (m_structuralIntegrity > 0.0f)
		{
			m_structuralIntegrity *= d->m_structuralDecay;
			if (m_structuralIntegrity < 0.0f)
				m_structuralIntegrity = 0.0f;
		}

		doAngleFX(m_accumulatedAngle, m_accumulatedAngle + m_toppleVelocity);

		m_accumulatedAngle += m_toppleVelocity;

		applyCrushingDamage(1.5707964f - m_accumulatedAngle);

		if (m_accumulatedAngle >= 1.5707964f)
		{
			m_toppleVelocity -= m_accumulatedAngle - 1.5707964f;
			m_accumulatedAngle = 1.5707964f;
			m_toppleState = TOPPLESTATE_WAITINGFORDONE;

			applyCrushingDamage(0.0f);
			doPhaseStuff(STRUCTURE_TOPPLE_PHASE_FINAL, getObject()->getPosition());

			if (lastDamageInfo == NULL || getDamageTypeFlag(d->m_damageFXTypes, lastDamageInfo->in.m_damageType))
				FXList::doFXObj(d->m_toppleDoneFX, getObject(), 0);

			m_toppleFrame = TheGameLogic->getFrame();
		}

		if (now >= m_nextBurstFrame)
		{
			doToppleDelayBurstFX();
			m_nextBurstFrame = now + GetGameLogicRandomValue(d->m_minToppleBurstDelay, d->m_maxToppleBurstDelay, "C:\\projects\\bfme2patch103\\bfme2\\Code\\GameEngine\\Source\\GameLogic\\Object\\Update\\StructureToppleUpdate.cpp", 0x117);
		}

		Object *building = getObject();
		Matrix3D xfrm = *building->getTransformMatrix();
		xfrm.In_Place_Pre_Rotate_X(-m_toppleVelocity * m_toppleDirection.y);
		xfrm.In_Place_Pre_Rotate_Y(m_toppleVelocity * m_toppleDirection.x);
		building->setTransformMatrix(&xfrm);
	}

	if (m_toppleState == TOPPLESTATE_WAITINGFORDONE)
	{
		if (m_toppleFrame <= TheGameLogic->getFrame())
		{
			Object *building = getObject();
			building->clearModelConditionState((UnsignedInt)5);
			building->setModelConditionState((ModelConditionFlagType)60);

			building->getBodyModule()->updateBodyParticleSystems();

			doToppleDoneStuff();

			m_toppleState = TOPPLESTATE_DONE;

			return UPDATE_SLEEP_FOREVER;
		}
	}

	return UPDATE_SLEEP_NONE;
}

// FUNCTION: BFME2 0x004A646B size=98 name=?rva004A646B@StructureToppleUpdateModuleData@@SAXPAVINI@@PAX1PBX@Z evidence=?:placeholder tier=A
void StructureToppleUpdateModuleData::rva004A646B(INI *ini, void *instance, void *store, const void *userData)
{
	StructureToppleUpdateModuleData *self = (StructureToppleUpdateModuleData *)instance;
	Int phase = ini->scanIndexList(ini->getNextToken(0), TheStructureTopplePhaseNames);
	for (const char *token = ini->getNextToken(0); token != 0; token = ini->getNextTokenOrNull(0))
	{
		const ObjectCreationList *ocl = TheObjectCreationListStore->findObjectCreationList(token);
		self->m_phaseOCLs[phase].push_back(ocl);
	}
}

// FUNCTION: BFME2 0x004A64CD size=78 name=?parseAngleFX@@YAXPAVINI@@PAX1PBX@Z evidence=N:ledger tier=B hypothesis:Z
void parseAngleFX(INI *ini, void *instance, void *store, const void *userData)
{
	StructureToppleAngleFX entry;
	INI::parseReal(ini, instance, &entry.m_angle, 0);
	entry.m_angle *= 0.017453292f;
	INI::parseFXList(ini, instance, &entry.m_fx, 0);
	((StructureToppleUpdateModuleData *)instance)->m_angleFXs.push_back(entry);
}

